//! The journal's stored shapes (ADR 0005, X1) against the golden fixture `compat/fixtures/journal.json`.
//!
//! Extension fixtures are generated by the Rust implementation, which shipped the feature first
//! (ADR 0005, Mitigations): a Go port writes code until it passes this file byte for byte, as Rust
//! does for the Go-generated core fixtures. Regenerate after an intentional format change:
//!
//! ```sh
//! EVT_UPDATE_FIXTURES=1 cargo test -p evt-compat --test journal_fixtures
//! ```

use evt_compat::scenario::compat_dir;
use std::time::{Duration, UNIX_EPOCH};

use photon_evt::journal::{
    ALLOCATION_KEY, Allocation, CompactionChunk, CompactionManifest, DEFAULT_MAX_ROW_BYTES,
    Journal, JournalCompactionStore, JournalRepository, JournalStore, LEASE_SORT_KEY,
    MANIFEST_SORT_KEY, MAX_CHUNK_BYTES, MAX_CHUNK_ROWS, MAX_SCOPE_BYTES, POSITION_WIDTH, Scope,
    audit_sk, chunk_sk, compact_with_lease, counter_view, encode_allocations, page, replay,
    row_size, row_view,
};
use photon_evt::wire::dynamo;
use photon_evt::{
    Commit, EntityId, EventSequence, EventVersion, FeatureManifest, MemRepository, Metadata,
    Repository, SerializedEvent, ViewRow,
};
use serde_json::{Value, json};

const COMMIT_ID: &str = "01JDXK7Q3W9B5N2M8P4R6TAVHY";

/// The clock the fixture's compaction runs at, in Unix seconds.
const FIXTURE_CLOCK: u64 = 1_792_000_000;

fn scope(name: &str) -> Scope {
    Scope::new(name).unwrap()
}

fn item(row: &ViewRow) -> Value {
    serde_json::to_value(dynamo::view_row_item(row).unwrap()).unwrap()
}

fn event(entity_id: &str, sequence: i64, payload: &str) -> SerializedEvent {
    SerializedEvent {
        id: format!("{entity_id}:{sequence}").into(),
        sequence: EventSequence(sequence),
        event_type: "account:deposited".into(),
        version: EventVersion(1),
        entity_id: entity_id.into(),
        entity_type: "account".into(),
        payload: payload.as_bytes().to_vec(),
        metadata: {
            let mut metadata = Metadata::default()
                .with_timestamp("2026-10-12T00:00:00Z")
                .with_command_id("cmd-0001");
            metadata.region = "us-west-2".into();
            metadata.commit_id = COMMIT_ID.into();

            metadata
        },
    }
}

/// The DynamoDB item of a compaction row.
async fn compaction_item(memory: &MemRepository, scope: &Scope, sort_key: &str) -> Value {
    item(
        &memory
            .read_compaction_row(scope, sort_key)
            .await
            .unwrap()
            .unwrap(),
    )
}

/// Every vector of the fixture, computed from the implementation.
async fn generate() -> Value {
    let keys: Vec<Value> = [
        ("world:7", 5),
        ("world:7/place:3", 1),
        ("é\u{10000}", 12),
        ("world:7", u64::MAX),
    ]
    .iter()
    .map(|(name, position)| {
        let scope = scope(name);

        json!({
            "scope": name,
            "position": position.to_string(),
            "rowPk": scope.row_pk(),
            "rowSk": photon_evt::journal::row_sk(*position),
            "counterPk": scope.counter_pk(),
            "counterSk": "COUNTER",
        })
    })
    .collect();

    let allocations: Vec<Value> = [
        ("one scope", vec![("world:7", 5)]),
        (
            "two scopes, ascending by scope bytes whatever the order given",
            vec![("world:7/place:3", 1), ("world:7", 5)],
        ),
        ("a position beyond 2^53", vec![("world:7", u64::MAX)]),
    ]
    .into_iter()
    .map(|(name, list)| {
        let mut allocations: Vec<Allocation> = list
            .iter()
            .map(|(scope_name, position)| Allocation::new(&scope(scope_name), *position))
            .collect();
        allocations.sort_by(|a, b| a.scope.as_bytes().cmp(b.scope.as_bytes()));

        json!({
            "name": name,
            "allocations": list
                .iter()
                .map(|(scope, position)| json!({ "scope": scope, "position": position.to_string() }))
                .collect::<Vec<_>>(),
            "extensionKey": ALLOCATION_KEY,
            "extensionValue": encode_allocations(&allocations),
        })
    })
    .collect();

    // A real commit through the journal: two events of one stream, one of another, into a world
    // scope and a place scope. The stored events, rows, and counters are what the journal wrote.
    // A fixed clock, so the lease expiry and the audit's completion time are stable.
    let memory =
        MemRepository::new().with_clock(|| UNIX_EPOCH + Duration::from_secs(FIXTURE_CLOCK));
    let journal = Journal::new(["account"], |event: &SerializedEvent| {
        let place = if event.entity_id.as_str() == "acct-1" {
            "place:3"
        } else {
            "place:4"
        };

        vec![scope("world:7"), scope(&format!("world:7/{place}"))]
    })
    .unwrap();
    let journaled = JournalRepository::new(memory.clone(), journal);

    let first = Commit::new(
        "acct-1",
        vec![
            event("acct-1", 1, r#"{"cents":500}"#),
            event("acct-1", 2, r#"{"cents":250}"#),
        ],
    );
    let second = Commit::new("acct-2", vec![event("acct-2", 1, r#"{"cents":75}"#)]);
    journaled.commit(first).await.unwrap();
    journaled.commit(second).await.unwrap();

    let mut events = memory.events(&EntityId::new("acct-1")).await.unwrap();
    events.extend(memory.events(&EntityId::new("acct-2")).await.unwrap());

    let state = replay(&events).unwrap();
    let rows: Vec<Value> = state
        .rows
        .iter()
        .map(|((scope, position), row)| {
            json!({
                "scope": scope.as_str(),
                "position": position.to_string(),
                "owner": row.entity_id,
                "size": row.payload.len(),
                "dynamoItem": item(row),
            })
        })
        .collect();
    let counters: Vec<Value> = state
        .counters
        .iter()
        .map(|(scope, position)| {
            json!({
                "scope": scope.as_str(),
                "position": position.to_string(),
                "dynamoItem": item(&counter_view(scope, *position)),
            })
        })
        .collect();

    // The live rows are exactly the replayed ones.
    for live in memory.views() {
        if live.pk.starts_with("journal") {
            assert!(
                state.views().contains(&live),
                "a live journal row differs from its replay: {live:?}"
            );
        }
    }

    // Compaction (X2): world:7 through position 2, under a 60-second lease taken and released.
    let world = scope("world:7");
    let report = compact_with_lease(&memory, &world, 2, "compactor-1", Duration::from_secs(60))
        .await
        .unwrap();
    let gone = match page(&memory, &world, 1, 10).await {
        Err(photon_evt::Error::JournalGone(gone)) => gone,
        other => panic!("a page below the floor: {other:?}"),
    };
    let compaction = json!({
        "note": "world:7 compacted through 2 by compactor-1, then read after 1",
        "limits": { "maxChunkRows": MAX_CHUNK_ROWS, "maxChunkBytes": MAX_CHUNK_BYTES },
        "keys": {
            "pk": photon_evt::journal::compaction_pk(&world),
            "lease": LEASE_SORT_KEY,
            "manifest": MANIFEST_SORT_KEY,
            "chunk0": chunk_sk(0),
            "audit2": audit_sk(2),
        },
        "manifestDigest": report.digest,
        "lease": compaction_item(&memory, &world, LEASE_SORT_KEY).await,
        "manifest": compaction_item(&memory, &world, MANIFEST_SORT_KEY).await,
        "chunks": [compaction_item(&memory, &world, &chunk_sk(0)).await],
        "audit": compaction_item(&memory, &world, &audit_sk(2)).await,
        "remainingRows": memory
            .read_rows(&world, 0, 10)
            .await
            .unwrap()
            .iter()
            .map(|row| row.position.to_string())
            .collect::<Vec<_>>(),
        "gone": {
            "httpStatus": photon_evt::journal::JournalGone::HTTP_STATUS,
            "after": gone.after.to_string(),
            "checkpoint": gone.checkpoint.to_string(),
            "chunkCount": gone.chunk_count,
            "digest": gone.digest,
            "resumeAfter": gone.resume_after().to_string(),
        },
    });
    let mut compacted = FeatureManifest::default();
    compacted.declare_stream_heads();
    compacted.declare_journal();
    compacted
        .features
        .insert(photon_evt::JOURNAL_COMPACTION_FEATURE.into(), 1);

    // The widest-row measure, which the pre-check and the guard share.
    let measured = row_size(&scope("world:7"), 1, &events[0]).unwrap();

    let mut manifest = FeatureManifest {
        version: 2,
        ..FeatureManifest::default()
    };
    manifest.declare_stream_heads();
    manifest.declare_journal();
    manifest.history_dependent.insert("account".into());

    json!({
        "limits": {
            "maxScopeBytes": MAX_SCOPE_BYTES,
            "positionWidth": POSITION_WIDTH,
            "defaultMaxRowBytes": DEFAULT_MAX_ROW_BYTES,
        },
        "keys": keys,
        "allocations": allocations,
        "commit": {
            "note": "acct-1 sequences 1 and 2, then acct-2 sequence 1, each committed once",
            "events": events
                .iter()
                .map(|event| serde_json::from_slice::<Value>(&event.to_json().unwrap()).unwrap())
                .collect::<Vec<_>>(),
            "rows": rows,
            "counters": counters,
            "measuredRowSize": { "scope": "world:7", "position": "1", "event": "acct-1:1", "bytes": measured },
        },
        "compaction": compaction,
        "compactionMarker": { "features": compacted.features_json() },
        "marker": {
            "features": manifest.features_json(),
            "historyDependent": manifest.history_dependent_json(),
            "dynamoItem": serde_json::to_value(dynamo::feature_marker_item(&manifest).unwrap()).unwrap(),
        },
    })
}

#[tokio::test]
async fn the_journal_fixture_matches_the_implementation() {
    let path = compat_dir().join("fixtures/journal.json");
    let generated = generate().await;

    if std::env::var_os("EVT_UPDATE_FIXTURES").is_some() {
        let mut text = serde_json::to_string_pretty(&generated).unwrap();
        text.push('\n');
        std::fs::write(&path, text).unwrap();

        return;
    }

    let stored: Value =
        serde_json::from_slice(&std::fs::read(&path).expect("read the journal fixture")).unwrap();

    assert_eq!(
        stored, generated,
        "compat/fixtures/journal.json is stale: regenerate it with EVT_UPDATE_FIXTURES=1"
    );
}

/// The fixture is also read back: the stored events replay to the stored rows and counters, and the
/// row items decode to the rows they encode. This is the check a Go port starts from.
#[tokio::test]
async fn the_fixture_events_replay_to_the_fixture_rows() {
    let stored: Value = serde_json::from_slice(
        &std::fs::read(compat_dir().join("fixtures/journal.json")).expect("read the fixture"),
    )
    .unwrap();

    let events: Vec<SerializedEvent> = stored["commit"]["events"]
        .as_array()
        .unwrap()
        .iter()
        .map(|event| SerializedEvent::from_json(event.to_string().as_bytes()).unwrap())
        .collect();
    let state = replay(events.iter().rev()).unwrap();

    for row in stored["commit"]["rows"].as_array().unwrap() {
        let key = (
            scope(row["scope"].as_str().unwrap()),
            row["position"].as_str().unwrap().parse::<u64>().unwrap(),
        );
        let replayed = &state.rows[&key];

        assert_eq!(item(replayed), row["dynamoItem"], "{key:?}");
        assert_eq!(replayed.payload.len() as u64, row["size"].as_u64().unwrap());
        assert_eq!(replayed.entity_id, row["owner"].as_str().unwrap());
        assert_eq!(
            photon_evt::journal::JournalRow::from_view(&key.0, replayed)
                .unwrap()
                .position,
            key.1
        );
    }
    assert_eq!(
        state.rows.len(),
        stored["commit"]["rows"].as_array().unwrap().len()
    );

    for counter in stored["commit"]["counters"].as_array().unwrap() {
        let scope = scope(counter["scope"].as_str().unwrap());
        let position: u64 = counter["position"].as_str().unwrap().parse().unwrap();

        assert_eq!(state.counters[&scope], position);
        assert_eq!(item(&counter_view(&scope, position)), counter["dynamoItem"]);
    }

    // The compaction rows decode: the manifest's digest is its payload's, its chunk digests are
    // the chunks', and the chunk holds the replayed rows 1..=2 of world:7.
    let world = scope("world:7");
    let payload = |item: &Value| item["payload"]["S"].as_str().unwrap().as_bytes().to_vec();
    let compaction = &stored["compaction"];
    let manifest = CompactionManifest::decode(&world, &payload(&compaction["manifest"])).unwrap();
    assert_eq!(
        manifest.digest(),
        compaction["manifestDigest"].as_str().unwrap()
    );
    assert_eq!(
        manifest.digest(),
        compaction["gone"]["digest"].as_str().unwrap()
    );
    let chunk_payload = payload(&compaction["chunks"][0]);
    let chunk = CompactionChunk::decode(&world, &chunk_payload).unwrap();
    assert_eq!((chunk.from, chunk.through), (1, 2));
    for row in &chunk.rows {
        let replayed = &state.rows[&(world.clone(), row.position)];
        assert_eq!(
            photon_evt::journal::encode_row(&world, row.position, &row.event).unwrap(),
            replayed.payload
        );
    }
    let fresh = photon_evt::journal::CompactionManifest {
        scope: world.clone(),
        checkpoint: 2,
        chunks: manifest.chunks.clone(),
    };
    assert_eq!(fresh, manifest);

    // The row of an event is its stored form: the payload parses back to the stored event.
    let first = row_view(&scope("world:7"), 1, &events[0]).unwrap();
    assert_eq!(
        stored["commit"]["measuredRowSize"]["bytes"]
            .as_u64()
            .unwrap(),
        first.payload.len() as u64
    );
}
